INSERT INTO public.ai_prompt_rules (escopo, conteudo, ordem, ativo, observacao)
VALUES
('global', 'NOVO DESTINO = CONFIRMAR ANTES DE BUSCAR: a cada novo destino pedido pelo cliente, reaproveite o contexto mas CONFIRME antes de pesquisar. Nunca presuma que os parâmetros da busca anterior continuam iguais. Pergunte em UMA mensagem: origem e quantidade de passageiros ("continuaria saindo de X e seriam as mesmas N pessoas?") e colete período/datas e quantidade de noites para AQUELA viagem ("tem alguma data ou período de preferência? Quantas noites gostariam de ficar, ou posso buscar a melhor relação custo-benefício?"). Só depois da resposta é que você pesquisa. Só depois disso, se não houver pacote pronto, diga que não encontrou e ofereça montar personalizado.', 23, true, 'Auditoria: Fortaleza sem confirmacao');